import{_ as t,o as e,c as s,a6 as a}from"./chunks/framework.Dtv7txdI.js";const k=JSON.parse('{"title":"Command-Line Flags","description":"","frontmatter":{},"headers":[],"relativePath":"v1/server/configuration/cli.md","filePath":"v1/server/configuration/cli.md","lastUpdated":1787648967000}'),n={name:"v1/server/configuration/cli.md"};function d(l,i,h,r,o,c){return e(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="command-line-flags" tabindex="-1">Command-Line Flags <a class="header-anchor" href="#command-line-flags" aria-label="Permalink to “Command-Line Flags”">​</a></h1><p>CLI flags are the <strong>strongest</strong> configuration layer: they beat <code>NITR_*</code> environment variables, which beat <code>nitr.toml</code>, which beats the built-in defaults.</p><p>Nitr keeps the flag surface deliberately small. Anything that belongs in a deployment&#39;s configuration belongs in <a href="./file"><code>nitr.toml</code></a> or an <a href="./env">environment variable</a>, where it can be reviewed and diffed.</p><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to “Global flags”">​</a></h2><p>Available on every command.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>-c</code>, <code>--config &lt;PATH&gt;</code></td><td>The TOML configuration file. Default: <code>./nitr.toml</code> — and if that file does not exist, Nitr runs with built-in defaults rather than failing.</td></tr><tr><td><code>--dev</code></td><td>Development mode: hot reload and error details in responses. Equivalent to <code>dev_mode = true</code> and to the <code>nitr dev</code> command.</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>Print the version and exit.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Print help. Works per command: <code>nitr build --help</code>.</td></tr></tbody></table><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/app/nitr.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/app/nitr.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span></span></code></pre></div><h2 id="per-command-flags" tabindex="-1">Per-command flags <a class="header-anchor" href="#per-command-flags" aria-label="Permalink to “Per-command flags”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>check</code></td><td><code>--print-config</code></td><td>Print the effective configuration after file + env + flag layering, then exit.</td></tr><tr><td><code>test</code></td><td><code>--filter &lt;SUBSTRING&gt;</code></td><td>Run only tests whose name or file name contains the substring.</td></tr><tr><td><code>migrate</code></td><td><code>--status</code></td><td>Report applied and pending migrations, applying nothing.</td></tr><tr><td><code>init</code></td><td><code>[DIR]</code></td><td>Directory to scaffold into. Default: the current directory.</td></tr><tr><td><code>init</code></td><td><code>--minimal</code></td><td>Write the four-file version instead of the full layout.</td></tr><tr><td><code>build</code></td><td><code>-o</code>, <code>--output &lt;PATH&gt;</code></td><td><strong>Required.</strong> Path of the single-file artifact to write.</td></tr></tbody></table><p>Full descriptions of each command are in <a href="./../cli">CLI commands</a>.</p><h2 id="signals" tabindex="-1">Signals <a class="header-anchor" href="#signals" aria-label="Permalink to “Signals”">​</a></h2><p>Not flags, but the other half of the runtime control surface:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Effect</th></tr></thead><tbody><tr><td><code>SIGHUP</code></td><td>Zero-downtime reload: rebuilds the Lua runtime pool. The process, listener and keep-alive connections survive. Also reachable as <a href="./../cli#reload"><code>nitr reload</code></a>.</td></tr><tr><td><code>SIGTERM</code> / <code>SIGINT</code></td><td>Graceful shutdown: stop accepting → flip <code>/readyz</code> to <code>503 draining</code> → let in-flight work finish within <code>[shutdown] grace</code> → exit. A truncated drain exits non-zero.</td></tr></tbody></table><h2 id="worked-examples" tabindex="-1">Worked examples <a class="header-anchor" href="#worked-examples" aria-label="Permalink to “Worked examples”">​</a></h2><p><strong>Run a specific application from anywhere.</strong> Paths inside the file resolve against the file&#39;s own directory:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/app/nitr.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p><strong>Develop against production-shaped configuration</strong>, without editing it:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitr.production.toml</span></span></code></pre></div><p><strong>Validate in CI</strong>, no port bound, no database touched:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitr.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p><strong>Debug the layering</strong>, when a value is not what you expected:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NITR_WORKERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print-config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workers</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># workers = 8</span></span></code></pre></div><p><strong>Run one test while iterating:</strong></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rejects an empty note&quot;</span></span></code></pre></div><p><strong>Build the deployable artifact:</strong></p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitr.production.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span></code></pre></div>`,26)])])}const g=t(n,[["render",d]]);export{k as __pageData,g as default};
